IndexAsyncWaiter::IndexAsyncWaiter(
    Index* proxy) : proxy_(proxy) {}

IndexAsyncWaiter::~IndexAsyncWaiter() = default;

void IndexAsyncWaiter::GetSize(
    uint64_t* out_num_items) {
  base::RunLoop loop;
  proxy_->GetSize(
      base::BindOnce(
          [](base::RunLoop* loop,
             uint64_t* out_num_items
,
             uint64_t num_items) {*out_num_items = std::move(num_items);
            loop->Quit();
          },
          &loop,
          out_num_items));
  loop.Run();
}

uint64_t IndexAsyncWaiter::GetSize(
    ) {
  uint64_t async_wait_result;
  GetSize(&async_wait_result);
  return async_wait_result;
}

void IndexAsyncWaiter::AddOrUpdate(
    const std::vector<::ash::local_search_service::Data>& data) {
  base::RunLoop loop;
  proxy_->AddOrUpdate(std::move(data),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



